func (q *Queries) ListPendingMessageDrafts(ctx context.Context, arg ListPendingMessageDraftsParams) ([]AuraMessageDrafts, error) {
	rows, err := q.db.Query(ctx, listPendingMessageDrafts, arg.IdentityID, arg.ConversationID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []AuraMessageDrafts{}
	for rows.Next() {
		var i AuraMessageDrafts
		if err := rows.Scan(
			&i.ID,
			&i.IdentityID,
			&i.ConversationID,
			&i.ToolCallID,
			&i.Recipe,
			&i.ToolName,
			&i.RegisteredToolName,
			&i.Action,
			&i.OriginalArgs,
			&i.OriginalFingerprint,
			&i.EffectiveArgs,
			&i.EffectiveFingerprint,
			&i.Status,
			&i.OutcomeCode,
			&i.ExpiresAt,
			&i.DispatchStartedAt,
			&i.ResolvedAt,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.ScheduledTaskID,
			&i.SendAt,
			&i.SenderAddress,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

